{
  "name": "bt_conn_fill_info",
  "confidence": "medium",
  "docstring": "Reads a Bluetooth connection context and fills an output information record with a sequence number, encoded flags, and up to two timestamped connection info entries.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "conn_idx",
    "a2": "info_buf",
    "v2": "conn_table_base",
    "v3": "conn_ctx",
    "v4": "conn_info_seq",
    "v5": "conn_info_flag",
    "v6": "current_time_ptr",
    "v7": "time_base_ptr",
    "v8": "entry",
    "v9": "entry_dst",
    "v10": "entry_count",
    "result": "conn_ctx"
  },
  "struct_hints": [
    {
      "offset": 16,
      "meaning": "valid flag for a 48-byte connection info entry"
    },
    {
      "offset": 20,
      "meaning": "entry type byte copied to the output info record"
    },
    {
      "offset": 24,
      "meaning": "8-byte address or identifier copied to the output info record"
    },
    {
      "offset": 32,
      "meaning": "entry mode or status byte used in filtering"
    },
    {
      "offset": 33,
      "meaning": "entry flag used in filtering"
    },
    {
      "offset": 36,
      "meaning": "entry timestamp tick used in output time calculation"
    },
    {
      "offset": 115,
      "meaning": "connection flag encoded as the 0x80 bit in output byte 10"
    },
    {
      "offset": 120,
      "meaning": "connection info sequence counter copied to output byte 9 and incremented"
    },
    {
      "offset": 135,
      "meaning": "connection filter or ignore flag"
    },
    {
      "offset": 136,
      "meaning": "number of info entries written during the last fill"
    }
  ]
}
